#!/usr/bin/env dotnet
// Regenerates src/LibOpus.Interop/Generated from the pinned libopus headers and the interop entry points
// in native/src/opus_interop.h.
//
//   dotnet run generate/Generate.cs
//
// The generated files are committed; consumers never run this. libopus's public headers declare the
// same API on every platform, so one host's output serves all of them.
//
// Prerequisites: the ClangSharpPInvokeGenerator local tool (dotnet tool restore) and an LLVM install
// whose clang major matches ClangMajor below. The libclang natives come from the packages referenced
// here. A libclang handed another major's builtin headers does not fail: it parses less and exits 0,
// which writes truncated bindings, so the major is checked rather than assumed.

#:package libclang.runtime.win-x64
#:package libclang.runtime.linux-x64
#:package libclang.runtime.osx-arm64
#:package libClangSharp.runtime.win-x64
#:package libClangSharp.runtime.linux-x64
#:package libClangSharp.runtime.osx-arm64
#:property PublishAot=false
#:property GenerateDocumentationFile=true
#:property NoWarn=$(NoWarn);CS1591

using System.Diagnostics;
using System.Formats.Tar;
using System.IO.Compression;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json.Nodes;

const int ClangMajor = 22;
const string LibClangVersion = "22.1.8";
const string LibClangSharpVersion = "22.1.8.2";

string repoRoot = FindRepoRoot();
string generateDir = Path.Combine(repoRoot, "generate");
string cacheDir = Path.Combine(generateDir, ".cache");
string outputRoot = Path.Combine(repoRoot, "src", "LibOpus.Interop", "Generated");

JsonObject opus = JsonNode.Parse(
    await File.ReadAllTextAsync(Path.Combine(generateDir, "inputs.json"))
)!["opus"]!.AsObject();
string source = await FetchAndExtractAsync(
    "opus",
    opus["url"]!.GetValue<string>(),
    opus["sha256"]!.GetValue<string>()
);
string include = Path.Combine(source, "include");
string interop = Path.Combine(repoRoot, "native", "src");

string work = Path.Combine(cacheDir, "work");
Directory.CreateDirectory(work);
string headerFile = Path.Combine(work, "header.txt");
await File.WriteAllTextAsync(
    headerFile,
    $"// <auto-generated/>\n// Generated by generate/Generate.cs from libopus {opus["version"]} headers. Do not edit.\n\n"
        + "#pragma warning disable CS1591 // Missing XML comment for publicly visible type or member\n"
);
string composite = Path.Combine(work, "opus_composite.h");
await File.WriteAllTextAsync(composite, "#include \"opus_interop.h\"\n");
string rawOut = Path.Combine(work, "out");
DeleteDirectory(rawOut);

List<string> rsp =
[
    "--config",
    "file=multi",
    "codegen=preview",
    "--generate",
    "macro-bindings",
    "file-scoped-namespaces",
    "empty-records",
    "funcs-with-body=false",
    "aggressive-inlining",
    // Every libopus signature is blittable (pointers and integers), so runtime marshalling is off for
    // the assembly, and the NativeTypeName attribute the declarations carry is generated with them.
    "disable-runtime-marshalling=true",
    "helper-types=true",
    "--log",
    "exclusions",
    "--header-file",
    headerFile,
    "--namespace",
    "LibOpus.Interop.Native",
    "--method-class-name",
    "Opus",
    "--library-path",
    "opus-interop",
    "--language",
    "c",
    "--std",
    "c11",
    "--include-directory",
    ToForwardSlashes(include),
    "--include-directory",
    ToForwardSlashes(interop),
    "--native-type-names-to-strip",
    ToForwardSlashes(include) + "/",
    "--native-type-names-to-strip",
    ToForwardSlashes(interop) + "/",
];
foreach (
    string header in new[]
    {
        Path.Combine(include, "opus.h"),
        Path.Combine(include, "opus_defines.h"),
        Path.Combine(include, "opus_types.h"),
        Path.Combine(include, "opus_multistream.h"),
        Path.Combine(include, "opus_projection.h"),
        Path.Combine(interop, "opus_interop.h"),
    }
)
{
    rsp.Add("--traverse");
    rsp.Add(ToForwardSlashes(header));
}

// The controls are variadic in libopus and are called through the interop entry points instead, and
// the request macros that wrap them (OPUS_SET_BITRATE(x) and the like) expand to argument lists, which
// have no C# form; their *_REQUEST numbers come through as constants.
foreach (
    string excluded in new[]
    {
        "opus_encoder_ctl",
        "opus_decoder_ctl",
        "opus_multistream_encoder_ctl",
        "opus_multistream_decoder_ctl",
        "opus_projection_encoder_ctl",
        "opus_projection_decoder_ctl",
        "opus_dred_decoder_ctl",
    }
)
{
    rsp.Add("--exclude");
    rsp.Add(excluded);
}

string rspPath = Path.Combine(work, "opus.rsp");
await File.WriteAllLinesAsync(rspPath, rsp);
(int exitCode, string log) = await RunToolAsync(
    $"@{rspPath}",
    "--file",
    composite,
    "--resource-directory",
    FindClangResourceDirectory(),
    "--output",
    rawOut
);
await File.WriteAllTextAsync(Path.Combine(work, "generator.log"), log);

// The generator's exit code is the number of diagnostics it reported, so it is only a failure when
// negative; macros that expand to argument lists are expected and reported as skipped.
List<string> unexpected =
[
    .. log.Split('\n')
        .Select(static l => l.Trim())
        .Where(static l => l.StartsWith("Error", StringComparison.Ordinal))
        .Where(static l => !l.Contains("macro", StringComparison.OrdinalIgnoreCase)),
];
if (exitCode < 0 || unexpected.Count > 0)
{
    Console.WriteLine($"FAIL  exit {exitCode}, {unexpected.Count} unexpected diagnostic(s)");
    foreach (string diagnostic in unexpected.Take(40))
    {
        Console.WriteLine($"      {diagnostic}");
    }

    return 1;
}

// libopus's public types are all opaque handles, which have no layout to test.
int files = Publish(rawOut, outputRoot);
Console.WriteLine($"ok    {files} files");
return 0;

async Task<(int ExitCode, string Log)> RunToolAsync(params string[] toolArgs)
{
    ProcessStartInfo start = new("dotnet")
    {
        RedirectStandardOutput = true,
        RedirectStandardError = true,
        WorkingDirectory = repoRoot,
    };
    start.ArgumentList.Add("tool");
    start.ArgumentList.Add("run");
    start.ArgumentList.Add("ClangSharpPInvokeGenerator");
    start.ArgumentList.Add("--");
    foreach (string arg in toolArgs)
    {
        start.ArgumentList.Add(arg);
    }

    string pathVariable =
        OperatingSystem.IsWindows() ? "PATH"
        : OperatingSystem.IsMacOS() ? "DYLD_LIBRARY_PATH"
        : "LD_LIBRARY_PATH";
    start.Environment[pathVariable] =
        LibClangNativeDirectories()
        + Path.PathSeparator
        + (Environment.GetEnvironmentVariable(pathVariable) ?? string.Empty);

    using Process process =
        Process.Start(start)
        ?? throw new InvalidOperationException("Could not start the generator.");
    Task<string> stdout = process.StandardOutput.ReadToEndAsync();
    Task<string> stderr = process.StandardError.ReadToEndAsync();
    await process.WaitForExitAsync();
    return (process.ExitCode, await stdout + await stderr);
}

int Publish(string from, string to)
{
    DeleteDirectory(to);
    if (!Directory.Exists(from))
    {
        return 0;
    }

    Directory.CreateDirectory(to);
    int count = 0;
    foreach (string file in Directory.EnumerateFiles(from, "*.cs"))
    {
        string text = File.ReadAllText(file).Replace("\r\n", "\n", StringComparison.Ordinal);
        File.WriteAllText(
            Path.Combine(to, Path.GetFileNameWithoutExtension(file) + ".g.cs"),
            text,
            new UTF8Encoding(false)
        );
        count++;
    }

    return count;
}

async Task<string> FetchAndExtractAsync(string name, string url, string sha256)
{
    string dir = Path.Combine(cacheDir, name);
    string archive = Path.Combine(cacheDir, $"{name}.tar.gz");
    string marker = Path.Combine(dir, ".sha256");
    if (File.Exists(marker) && (await File.ReadAllTextAsync(marker)).Trim() == sha256)
    {
        return SingleSubdirectory(dir);
    }

    Directory.CreateDirectory(cacheDir);
    using (HttpClient http = new())
    {
        await using Stream body = await http.GetStreamAsync(new Uri(url));
        await using FileStream file = File.Create(archive);
        await body.CopyToAsync(file);
    }

    string actual;
    await using (FileStream hashed = File.OpenRead(archive))
    {
        actual = Convert.ToHexStringLower(await SHA256.HashDataAsync(hashed));
    }

    if (!string.Equals(actual, sha256, StringComparison.OrdinalIgnoreCase))
    {
        throw new InvalidDataException(
            $"{name}: {url} hashed to {actual}, inputs.json pins {sha256}."
        );
    }

    DeleteDirectory(dir);
    Directory.CreateDirectory(dir);
    await using (FileStream file = File.OpenRead(archive))
    await using (GZipStream gzip = new(file, CompressionMode.Decompress))
    {
        await TarFile.ExtractToDirectoryAsync(gzip, dir, overwriteFiles: true);
    }

    await File.WriteAllTextAsync(marker, sha256);
    File.Delete(archive);
    return SingleSubdirectory(dir);
}

static string FindClangResourceDirectory()
{
    string[] candidates =
        OperatingSystem.IsWindows() ? [$@"C:\Program Files\LLVM\lib\clang\{ClangMajor}"]
        : OperatingSystem.IsMacOS()
            ?
            [
                $"/opt/homebrew/opt/llvm@{ClangMajor}/lib/clang/{ClangMajor}",
                $"/opt/homebrew/opt/llvm/lib/clang/{ClangMajor}",
            ]
        : [$"/usr/lib/llvm-{ClangMajor}/lib/clang/{ClangMajor}", $"/usr/lib/clang/{ClangMajor}"];
    return candidates.FirstOrDefault(static c =>
            File.Exists(Path.Combine(c, "include", "stddef.h"))
        )
        ?? throw new InvalidOperationException(
            $"No clang {ClangMajor} resource directory found. Install LLVM {ClangMajor}; libclang {LibClangVersion} handed another major's builtin headers parses less and still exits 0."
        );
}

static string LibClangNativeDirectories()
{
    string packages =
        Environment.GetEnvironmentVariable("NUGET_PACKAGES")
        ?? Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),
            ".nuget",
            "packages"
        );
    string rid = RuntimeInformation.RuntimeIdentifier;
    string clang = Path.Combine(
        packages,
        $"libclang.runtime.{rid}",
        LibClangVersion,
        "runtimes",
        rid,
        "native"
    );
    string clangSharp = Path.Combine(
        packages,
        $"libclangsharp.runtime.{rid}",
        LibClangSharpVersion,
        "runtimes",
        rid,
        "native"
    );
    return Directory.Exists(clang) && Directory.Exists(clangSharp)
        ? clang + Path.PathSeparator + clangSharp
        : throw new InvalidOperationException(
            $"libclang natives for {rid} were not restored under {packages}."
        );
}

static string SingleSubdirectory(string dir) =>
    Directory.GetDirectories(dir) is [string only]
        ? only
        : throw new InvalidDataException($"{dir} should hold one extracted root.");

static void DeleteDirectory(string dir)
{
    if (Directory.Exists(dir))
    {
        Directory.Delete(dir, recursive: true);
    }
}

static string ToForwardSlashes(string path) => path.Replace('\\', '/');

static string FindRepoRoot()
{
    for (
        DirectoryInfo? current = new(Environment.CurrentDirectory);
        current is not null;
        current = current.Parent
    )
    {
        if (File.Exists(Path.Combine(current.FullName, "generate", "inputs.json")))
        {
            return current.FullName;
        }
    }

    throw new InvalidOperationException("Run from inside the repository.");
}
